import os, glob, re

def load_grids():
    """Load all grid data from session logs."""
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    sessions_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

    with open(sessions_file, 'r') as f:
        content = f.read().replace('\\n', '\n')

    G = {}
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    matches = list(re.finditer(pattern, content))

    last_match = None
    i = 0
    while i < len(matches):
        m = matches[i]
        k, h, w = m[1], int(m[2]), int(m[3])
        # Extract until next match or end
        if i + 1 < len(matches):
            end_pos = matches[i + 1].start()
        else:
            end_pos = len(content)

        rows_str = content[m.end():end_pos]
        rows = []
        for line in rows_str.split('\n'):
            if line.strip():
                row_parts = line.strip().split()
                if all(x.isdigit() for x in row_parts):
                    rows.append([int(x) for x in row_parts])
                elif row_parts and row_parts[0].isdigit():
                    # Single number on line
                    pass

        # Try to parse the rows directly
        if len(rows) > 0 and len(rows[-1]) == 0:
            rows.pop()

        if len(rows) == h and all(len(r) == w for r in rows):
            if k not in G:
                G[k] = rows

        i += 2

    return G

G = load_grids()
print("Loaded grids:", sorted(G.keys()))
for name, grid in G.items():
    print(f"\n{name} ({len(grid)}x{len(grid[0])}):")
    for row in grid:
        print(row)

